    /// <summary>
    /// Load GLP source code.
    /// Returns true if successful. Throws on parse/compile errors.
    /// </summary>
    public bool LoadSource(string source, string? filename = null)
    {
        var name = filename ?? "_source_";

        // Parse to get Module AST for type checking.
        var lexer  = new Lexer(source);
        var tokens = lexer.Tokenize();
        var parser = new Parser(tokens);
        var module = parser.ParseModule();

        // Discover ancestor scope from self.glp hierarchy (if loading from a file).
        TypeEnvironment? ancestorScope = null;
        if (name != "_source_" && name != "__mad_predicates__" &&
            name != "__root_self__" &&
            File.Exists(name))
        {
            var rootDir = _FindProjectRoot(name);
            if (rootDir != null)
            {
                var chain = ModuleHierarchy.DiscoverSelfChain(targetFile: name, rootDir: rootDir);
                if (chain.Count > 0)
                    ancestorScope = _BuildAncestorScope(chain);
            }
        }

        // Type check if program has procedure declarations.
        if (module.ProcDeclarations.Count > 0)
        {
            var ast              = new Program(module.Procedures, module.Line, module.Column);
            var partialEvaluator = new PartialEvaluator();
            var transformedAst   = partialEvaluator.TransformDefinedGuards(ast);

            var typeResult = TypeCheckerDriver.CheckModule(
                module,
                transformedProcedures: transformedAst.Procedures,
                ancestorScope: ancestorScope);

            if (!typeResult.IsWellTyped)
            {
                var errors = string.Join("\n", typeResult.Errors.Select(e => $"  {e.Message} at line {e.Line}"));
                if (StrictTypes)
                    throw new InvalidOperationException($"Type checking failed:\n{errors}");
                // Non-strict mode: print warning and continue.
                Console.WriteLine($"[TYPE WARNING] Type errors found:\n{errors}");
            }
        }

        // Compile.
        var program = _compiler.Compile(source);
        _loadedPrograms[name] = program;

        var moduleInfo = _ExtractModuleInfo(source, program, name);
        _loadedModules[moduleInfo.Name] = moduleInfo;

        // Auto-activate modules with exports for dynamic dispatch.
        // Merge with root self.glp so dispatched procedures can find :=/2 etc.
        if (moduleInfo.HasExports)
        {
            _loadedPrograms.TryGetValue("__root_self__", out var rootSelf);
            var moduleBytecode = rootSelf != null ? program.Merge(rootSelf) : program;
            GlpActivation.ActivateModule(
                rt: _runtime,
                serveBytecode: _serveBytecode,
                moduleBytecode: moduleBytecode,
                moduleName: moduleInfo.Name);
        }

        return true;
    }

    /// <summary>
    /// Load an entire project directory via static linking.
    /// Discovers all modules, type-checks each independently, links into a
    /// single flat program, and compiles it.
    /// </summary>
    /// <param name="projectDir">Path to the project root directory.</param>
    /// <param name="topModuleName">Top module name; auto-detected if null.</param>
    public bool LoadProject(string projectDir, string? topModuleName = null)
    {
        var modules = ProjectLinker.DiscoverProject(projectDir, rootSelfGlpPath: _rootSelfGlpPath);
        if (modules.Count == 0)
            throw new InvalidOperationException($"No modules found in {projectDir}");

        ProjectLinker.TypeCheckProject(modules);

        var top    = topModuleName ?? _DetectTopModule(modules.ToList());
        var linked = ProjectLinker.LinkProject(modules, top);
        var program = _compiler.CompileProgram(
            linked.Program,
            procDeclarations: linked.ProcDeclarations);
        _loadedPrograms["__project__"] = program;

        return true;
    }

    /// <summary>
    /// Run a goal and return the result asynchronously.
    /// </summary>
    public async Task<ExecutionResult> RunGoalAsync(string goalText)
    {
        try
        {
            var trimmed = goalText.Trim();
            if (trimmed.EndsWith("."))
                trimmed = trimmed.Substring(0, trimmed.Length - 1).Trim();

            if (_IsConjunction(trimmed))
                return await _RunConjunctionAsync(trimmed);

            return await _RunSingleGoalAsync(trimmed);
        }
        catch (Exception e)
        {
            return new ExecutionResult(status: ExecutionStatus.Failed, error: e.ToString());
        }
    }

    /// <summary>
    /// Activate a loaded module for dynamic dispatch.
    /// Creates a GLP channel, spawns serve(Module, ChannelReader?).
    /// The module must have been loaded and must have exported procedures.
    /// </summary>
    public void ActivateDynamicModule(string moduleName)
    {
        // Skip if already activated (LoadSource auto-activates modules with exports).
        if (_runtime.GlpChannels.ContainsKey(moduleName))
            return;

        if (!_loadedModules.TryGetValue(moduleName, out var moduleInfo))
            throw new InvalidOperationException($"Module \"{moduleName}\" not loaded");

        if (!moduleInfo.HasExports)
            throw new InvalidOperationException($"Module \"{moduleName}\" has no exported procedures");

        // Merge with root self.glp so dispatched procedures can find :=/2 etc.
        _loadedPrograms.TryGetValue("__root_self__", out var rootSelf);
        var moduleBytecode = rootSelf != null ? moduleInfo.Program.Merge(rootSelf) : moduleInfo.Program;
        GlpActivation.ActivateModule(
            rt: _runtime,
            serveBytecode: _serveBytecode,
            moduleBytecode: moduleBytecode,
            moduleName: moduleName);
    }

