    /// <summary>
    /// Get the combined bytecode program from all loaded sources.
    /// <para>
    /// Enforces module boundaries (spec §19.3): REPL goals can only resolve
    /// procedures that are exported, or defined in root self.glp / project.
    /// All bytecode is included (internal procedures still execute when called
    /// by exported procedures), but only exported labels are addressable as entry points.
    /// </para>
    /// <remarks>Specification §19.3 / §19.6.</remarks>
    /// </summary>
    public BytecodeProgram CombinedProgram
    {
        get
        {
            var allOps = new List<object>();
            foreach (var loaded in _loadedPrograms.Values)
                allOps.AddRange(loaded.Instructions);
            var combined = new BytecodeProgram(allOps);

            // Build the set of allowed labels.
            var allowedLabels = new HashSet<string>(StringComparer.Ordinal);

            // Root self.glp: all labels are visible everywhere (ancestor scoping §19.6).
            if (_loadedPrograms.TryGetValue("__root_self__", out var rootSelf))
                foreach (var k in rootSelf.Labels.Keys)
                    allowedLabels.Add(k);

            // Project: all labels are visible (static linking already handles exports).
            if (_loadedPrograms.TryGetValue("__project__", out var project))
                foreach (var k in project.Labels.Keys)
                    allowedLabels.Add(k);

            // Per-module: top-level programs have all labels; declared modules expose only exports.
            foreach (var mi in _loadedModules.Values)
            {
                if (mi.IsTopLevel)
                {
                    foreach (var k in mi.Program.Labels.Keys)
                        allowedLabels.Add(k);
                }
                else
                {
                    foreach (var k in mi.ExportedLabels)
                        allowedLabels.Add(k);
                }
            }

            // Collect-then-remove pattern (Dictionary has no RemoveWhere;
            // avoids InvalidOperationException: Collection was modified).
            var keysToRemove = combined.Labels
                .Where(kvp => !allowedLabels.Contains(kvp.Key))
                .Select(kvp => kvp.Key)
                .ToList();
            foreach (var k in keysToRemove)
                combined.Labels.Remove(k);

            return combined;
        }
    }

