    private async Task<ExecutionResult> _RunSingleGoalAsync(string trimmed)
    {
        var parseInput = $"{trimmed}.";
        var lexer  = new Lexer(parseInput);
        var tokens = lexer.Tokenize();
        var parser = new Parser(tokens);
        var ast    = parser.Parse();

        if (ast.Procedures.Count == 0)
            return new ExecutionResult(status: ExecutionStatus.Failed, error: "No goal found");

        var proc = ast.Procedures[0];
        if (proc.Clauses.Count == 0)
            return new ExecutionResult(status: ExecutionStatus.Failed, error: "No clauses in goal");

        var goalClause = proc.Clauses[0];
        var goalAtom   = goalClause.Head;
        var functor    = goalAtom.Functor;
        var arity      = goalAtom.Arity;
        var args       = goalAtom.Args;

        var program        = CombinedProgram;
        var procedureLabel = $"{functor}/{arity}";
        if (!program.Labels.TryGetValue(procedureLabel, out var entryPC))
            return new ExecutionResult(
                status: ExecutionStatus.Failed,
                error: $"Predicate {procedureLabel} not found");

        var queryVarWriters = new Dictionary<string, int>(StringComparer.Ordinal);
        var varNameToId     = new Dictionary<string, int>(StringComparer.Ordinal);
        var argSlots        = new Dictionary<int, RtTerm>();

        for (int i = 0; i < args.Count; i++)
            _SetupArgument(_runtime, args[i], i, argSlots, queryVarWriters, varNameToId);

        var env = new CallEnv(args: argSlots);
        _runtime.SetGoalEnv(_goalId, env);
        _runtime.SetGoalProgram(_goalId, "main");

        var module = _FindModuleForProcedure(procedureLabel);
        if (module != null)
        {
            var modCtx = _BuildModuleContext(module, program);
            if (modCtx != null)
                _runtime.SetGoalModuleContext(_goalId, modCtx);
        }

        var runner    = new BytecodeRunner(program);
        var scheduler = new Scheduler(
            rt:      _runtime,
            runners: new Dictionary<object?, BytecodeRunner> { { "main", runner } });
        scheduler.ResetDisplayNumbering();
        scheduler.SetQueryVarNames(queryVarWriters);

        EquivTrace.Reset();  // feature-020: begin a fresh candidate trace for this goal
        _runtime.Gq.Enqueue(new GoalRef(_goalId, entryPC));
        _goalId++;

        var result = await scheduler.DrainAsyncWithStatus(
            maxCycles:    MaxCycles,
            debug:        DebugTrace,
            showBindings: false,
            debugOutput:  DebugOutput);

        // Collect bindings.
        var bindings = new Dictionary<string, RtTerm?>(StringComparer.Ordinal);
        foreach (var entry in queryVarWriters)
        {
            var varName  = entry.Key;
            var writerId = entry.Value;
            if (_runtime.Heap.IsBound(writerId))
                bindings[varName] = _runtime.Heap.Dereference(new RtVarRef(writerId));
            else
                bindings[varName] = null;
        }

        EquivTrace.Out(_StatusWord(result.Status),
            bindings.Select(b => (b.Key, EquivTrace.ShapeOf(_ResolveDeepForTrace(b.Value)))));

        return new ExecutionResult(status: result.Status, bindings: bindings);
    }

    // feature-020: map ExecutionStatus → the OUT wire-format status word
    // (normalize.Status: succeed|suspend|fail — note "succeed", not "success").
    private static string _StatusWord(ExecutionStatus s) => s switch
    {
        ExecutionStatus.Succeeded => "succeed",
        ExecutionStatus.Suspended => "suspend",
        _ => "fail",
    };

    // feature-020 (finding #3): recursively dereference a query binding through
    // the heap so EquivTrace.ShapeOf renders the FULL ground shape for the OUT
    // record (e.g. ./2(const(a),./2(const(c),const(nil)))) — a single top-level
    // Heap.Dereference leaves a struct's args as VarRefs, which ShapeOf would
    // render as the shallow ./2(var,var), diverging from the Dart golden's fully
    // resolved `Zs = [a, c]`. Candidate-side trace instrumentation ONLY: it does
    // NOT change ExecutionResult.Bindings or any runner semantics, and is reached
    // only when GLP_EQUIV_TRACE is set (the binding Select is enumerated lazily
    // inside EquivTrace.Out, past its Ready() gate).
    private RtTerm? _ResolveDeepForTrace(RtTerm? term, int depth = 0)
    {
        if (term == null || depth > 32) return term;
        var d = _runtime.Heap.Dereference(term);
        if (d is RtStructTerm s)
        {
            var args = new List<RtTerm>(s.Args.Count);
            foreach (var a in s.Args)
                args.Add(_ResolveDeepForTrace(a, depth + 1) ?? a);
            return new RtStructTerm(s.Functor, args);
        }
        return d;
    }

    private async Task<ExecutionResult> _RunConjunctionAsync(string trimmed)
    {
        var parseInput = $"_conj_wrapper_ :- {trimmed}.";
        var lexer  = new Lexer(parseInput);
        var tokens = lexer.Tokenize();
        var parser = new Parser(tokens);
        var ast    = parser.Parse();

        if (ast.Procedures.Count == 0 || ast.Procedures[0].Clauses.Count == 0)
            return new ExecutionResult(status: ExecutionStatus.Failed, error: "Could not parse conjunction");

        var clause = ast.Procedures[0].Clauses[0];
        if (clause.Body == null || clause.Body.Count == 0)
            return new ExecutionResult(status: ExecutionStatus.Failed, error: "No goals in conjunction");

        var goals = clause.Body
            .Select(g => new Atom(g.Functor, g.Args, g.Line, g.Column))
            .ToList();

        var program         = CombinedProgram;
        var queryVarWriters = new Dictionary<string, int>(StringComparer.Ordinal);
        var varNameToId     = new Dictionary<string, int>(StringComparer.Ordinal);

        // Scheduler and runner created ONCE before loop (reused across all goals).
        var runner    = new BytecodeRunner(program);
        var scheduler = new Scheduler(
            rt:      _runtime,
            runners: new Dictionary<object?, BytecodeRunner> { { "main", runner } });
        scheduler.ResetDisplayNumbering();

        var allSucceeded = true;
        var anySuspended = false;

        EquivTrace.Reset();  // feature-020: begin a fresh candidate trace for this conjunction

        foreach (var goal in goals)
        {
            var goalFunctor    = goal.Functor;
            var goalArity      = goal.Args.Count;
            var goalArgs       = goal.Args;
            var procedureLabel = $"{goalFunctor}/{goalArity}";

            if (!program.Labels.TryGetValue(procedureLabel, out var entryPC))
                return new ExecutionResult(
                    status: ExecutionStatus.Failed,
                    error: $"Predicate {procedureLabel} not found");

            var argSlots = new Dictionary<int, RtTerm>();
            for (int i = 0; i < goalArgs.Count; i++)
                _SetupConjunctionArg(_runtime, goalArgs[i], i, argSlots, queryVarWriters, varNameToId);

            var env = new CallEnv(args: argSlots);
            _runtime.SetGoalEnv(_goalId, env);
            _runtime.SetGoalProgram(_goalId, "main");

            var module = _FindModuleForProcedure(procedureLabel);
            if (module != null)
            {
                var modCtx = _BuildModuleContext(module, program);
                if (modCtx != null)
                    _runtime.SetGoalModuleContext(_goalId, modCtx);
            }

            scheduler.SetQueryVarNames(queryVarWriters);
            _runtime.Gq.Enqueue(new GoalRef(_goalId, entryPC));
            _goalId++;

            var result = await scheduler.DrainAsyncWithStatus(
                maxCycles:    MaxCycles,
                debug:        DebugTrace,
                showBindings: false,
                debugOutput:  DebugOutput);

            if (result.Status == ExecutionStatus.Failed)
            {
                allSucceeded = false;
                break;
            }
            else if (result.Status == ExecutionStatus.Suspended)
            {
                anySuspended = true;
            }
        }

        // Collect bindings.
        var bindings = new Dictionary<string, RtTerm?>(StringComparer.Ordinal);
        foreach (var entry in queryVarWriters)
        {
            var varName  = entry.Key;
            var writerId = entry.Value;
            if (_runtime.Heap.IsBound(writerId))
                bindings[varName] = _runtime.Heap.Dereference(new RtVarRef(writerId));
            else
                bindings[varName] = null;
        }

        var status = !allSucceeded
            ? ExecutionStatus.Failed
            : (anySuspended ? ExecutionStatus.Suspended : ExecutionStatus.Succeeded);

        EquivTrace.Out(_StatusWord(status),
            bindings.Select(b => (b.Key, EquivTrace.ShapeOf(_ResolveDeepForTrace(b.Value)))));

        return new ExecutionResult(status: status, bindings: bindings);
    }

    /// <summary>
    /// Detect the top module in a project.
    /// Prefers module with imported procedure declarations; falls back to most procedures.
    /// In-place sort preserved verbatim (NOT OrderByDescending).
    /// </summary>
    private string _DetectTopModule(List<DiscoveredModule> modules)
    {
        var withImports = modules
            .Where(m => m.ModuleAst.ProcDeclarations.Any(d => d.Imported))
            .ToList();
        if (withImports.Count == 1)
            return withImports[0].ModuleName;

        // Fallback: module with the most procedures (mutate-sort-descending, in-place).
        modules.Sort((a, b) => b.ModuleAst.Procedures.Count.CompareTo(a.ModuleAst.Procedures.Count));
        return modules[0].ModuleName;
    }

    /// <summary>
    /// Depth-tracking comma scanner to detect conjunctions.
    /// Reserved keyword <c>char</c> renamed to <c>ch</c>.
    /// </summary>
    private bool _IsConjunction(string query)
    {
        int depth = 0;
        for (int i = 0; i < query.Length; i++)
        {
            var ch = query[i];
            if (ch == '(' || ch == '[')
                depth++;
            else if (ch == ')' || ch == ']')
                depth--;
            else if (ch == ',' && depth == 0)
                return true;
        }
        return false;
    }

    /// <summary>
    /// Extract module information from source using three regex scrapes.
    /// Ordered List for imports (1-based ImportTable order — LOAD-BEARING).
    /// </summary>
    private ModuleInfo _ExtractModuleInfo(string source, BytecodeProgram program, string filename)
    {
        string name;
        bool   isTopLevel;

        var moduleMatch = Regex.Match(source, @"-module\((\w+)\)\.");
        if (moduleMatch.Success)
        {
            name       = moduleMatch.Groups[1].Value;
            isTopLevel = false;
        }
        else
        {
            name       = _ModuleNameFromFilename(filename);
            isTopLevel = true;
        }

        // Extract imported module names from `imported procedure Module#Proc(...)` declarations.
        // The order of unique module names determines the import index (1-based),
        // matching the compiler's ImportTable.addImport() order.
        var imports       = new List<string>();
        var importPattern = new Regex(@"imported\s+procedure\s+(\w+)#");
        foreach (Match m in importPattern.Matches(source))
        {
            var moduleName = m.Groups[1].Value;
            if (!imports.Contains(moduleName))
                imports.Add(moduleName);
        }

        // Detect exported procedures from `exported procedure` declarations.
        var exportedLabels = new HashSet<string>(StringComparer.Ordinal);
        var exportPattern  = new Regex(@"exported\s+procedure\s+(\w+)\s*\(");
        foreach (Match m in exportPattern.Matches(source))
        {
            var functor = m.Groups[1].Value;
            foreach (var label in program.Labels.Keys)
            {
                if (label.StartsWith($"{functor}/", StringComparison.Ordinal))
                    exportedLabels.Add(label);
            }
        }
        var hasExports = exportedLabels.Count > 0;

        return new ModuleInfo(
            name:           name,
            program:        program,
            imports:        imports,
            hasExports:     hasExports,
            exportedLabels: exportedLabels,
            isTopLevel:     isTopLevel);
    }

    /// <summary>
    /// Extract module name from filename.
    /// Dart-fidelity: uses forward-slash split (NOT Path.GetFileName).
    /// </summary>
    private string _ModuleNameFromFilename(string filename)
    {
        var baseName = filename.Split('/').Last();
        if (baseName.EndsWith(".glp", StringComparison.Ordinal))
            return baseName.Substring(0, baseName.Length - 4);
        return baseName;
    }

    /// <summary>
    /// Walk up from the file's directory to find the topmost directory containing self.glp.
    /// Topmost-wins (last-match-wins overwrite).
    /// </summary>
    private string? _FindProjectRoot(string filePath)
    {
        var dir  = new DirectoryInfo(Path.GetDirectoryName(filePath) ?? ".");
        string? root = null;
        while (true)
        {
            var selfGlp = new FileInfo(Path.Combine(dir.FullName, "self.glp"));
            if (selfGlp.Exists)
                root = dir.FullName;
            var parent = dir.Parent;
            if (parent == null || parent.FullName == dir.FullName)
                break;
            dir = parent;
        }
        return root;
    }

    /// <summary>Build prelude + chain scope (WITHOUT the target module).</summary>
    private TypeEnvironment _BuildAncestorScope(IReadOnlyList<string> chain)
    {
        var env = TypeEnvironmentBuilder.BuildPreludeEnvironment();

        // Include root self.glp (programs/self.glp) as first scope layer.
        if (File.Exists(_rootSelfGlpPath))
            env = _MergeModuleIntoEnv(env, File.ReadAllText(_rootSelfGlpPath));

        var rootSelfGlpFull = new FileInfo(_rootSelfGlpPath).FullName;
        foreach (var selfGlpPath in chain)
        {
            // Skip if this chain entry IS the root self.glp (avoid double-merging).
            if (new FileInfo(selfGlpPath).FullName == rootSelfGlpFull)
                continue;
            env = _MergeModuleIntoEnv(env, File.ReadAllText(selfGlpPath));
        }
        return env;
    }

    /// <summary>Parse GLP source and merge its types/procedures into an environment.</summary>
    private TypeEnvironment _MergeModuleIntoEnv(TypeEnvironment env, string source)
    {
        var lexer      = new Lexer(source);
        var tokens     = lexer.Tokenize();
        var parser     = new Parser(tokens);
        var selfModule = parser.ParseModule();

        // Extract templates BEFORE expansion removes them.
        var selfTemplates = new Dictionary<string, TypeDef>(StringComparer.Ordinal);
        foreach (var td in selfModule.TypeDefs)
            if (td.IsParameterized) selfTemplates[td.Name] = td;

        // Expand parameterized types.
        var expandedModule = ParamExpansion.ExpandParameterizedTypes(
            selfModule,
            knownTypeNames:    new HashSet<string>(env.Types.Keys, StringComparer.Ordinal),
            externalTemplates: env.TypeTemplates);

        var types = new Dictionary<string, TypeDef>(StringComparer.Ordinal);
        foreach (var t in expandedModule.TypeDefs)
            types[t.Name] = t;

        var procs = new Dictionary<string, ProcDecl>(StringComparer.Ordinal);
        foreach (var p in expandedModule.ProcDeclarations)
            procs[p.QualifiedKey] = p;

        var paramProcs = new Dictionary<string, ProcDecl>(StringComparer.Ordinal);
        foreach (var p in expandedModule.ParamProcDecls)
            paramProcs[p.QualifiedKey] = p;

        return env.Merge(new TypeEnvironment(types, procs,
            paramProcDecls: paramProcs,
            typeTemplates:  selfTemplates));
    }

    /// <summary>Linear scan for the first module defining the given procedure label. First-match-wins.</summary>
    private ModuleInfo? _FindModuleForProcedure(string procedureLabel)
    {
        foreach (var module in _loadedModules.Values)
        {
            if (module.Program.Labels.ContainsKey(procedureLabel))
                return module;
        }
        return null;
    }

    /// <summary>
    /// Build a ReplModuleContext for the given module against the combined program.
    /// 1-based import index — LOAD-BEARING (matches ImportTable.addImport() order).
    /// Returns null if the module has no imports.
    /// </summary>
    private ReplModuleContext? _BuildModuleContext(ModuleInfo module, BytecodeProgram combinedProg)
    {
        if (module.Imports.Count == 0)
            return null;

        var imports = new Dictionary<int, ReplModuleTarget>();
        for (int i = 0; i < module.Imports.Count; i++)
        {
            var importName = module.Imports[i];
            if (_loadedModules.TryGetValue(importName, out var target))
                imports[i + 1] = new ReplModuleTarget(target.Name, target.Program);
        }

        return new ReplModuleContext(
            moduleName:      module.Name,
            imports:         imports,
            combinedProgram: combinedProg,
            programKey:      "main");
    }

    private void _SetupArgument(
        GlpRuntimeEngine runtime,
        Compiler.Term arg,
        int argSlot,
        IDictionary<int, RtTerm> argSlots,
        IDictionary<string, int> queryVarWriters,
        IDictionary<string, int> varNameToId)
    {
        if (arg is VarTerm varTerm)
        {
            var baseName = varTerm.Name;
            if (varNameToId.TryGetValue(baseName, out var existingId))
            {
                argSlots[argSlot] = new RtVarRef(
                    varTerm.IsReader ? runtime.Heap.PairedReaderAddr(existingId) : existingId);
            }
            else
            {
                var (writerId, readerId) = runtime.Heap.AllocateVariable();
                varNameToId[baseName] = writerId;
                if (!varTerm.IsReader)
                    queryVarWriters[baseName] = writerId;
                argSlots[argSlot] = new RtVarRef(varTerm.IsReader ? readerId : writerId);
            }
        }
        else if (arg is ListTerm listArg)
        {
            var (writerId, readerId) = runtime.Heap.AllocateVariable();
            var listValue = _BuildListTerm(runtime, listArg, queryVarWriters, varNameToId);
            if (listValue is RtConstTerm ct)
                runtime.Heap.BindWriterConst(writerId, ct.Value);
            else if (listValue is RtStructTerm st)
                runtime.Heap.BindWriterStruct(writerId, st.Functor, st.Args.ToList());
            argSlots[argSlot] = new RtVarRef(readerId);
        }
        else if (arg is Compiler.ConstTerm constArg)
        {
            var (writerId, readerId) = runtime.Heap.AllocateVariable();
            runtime.Heap.BindWriterConst(writerId, constArg.Value);
            argSlots[argSlot] = new RtVarRef(readerId);
        }
        else if (arg is Compiler.StructTerm structArg)
        {
            var (writerId, readerId) = runtime.Heap.AllocateVariable();
            var structValue = _BuildStructTerm(runtime, structArg, queryVarWriters, varNameToId) as RtStructTerm
                              ?? throw new InvalidOperationException("BuildStructTerm must return RtStructTerm");
            runtime.Heap.BindWriterStruct(writerId, structValue.Functor, structValue.Args.ToList());
            argSlots[argSlot] = new RtVarRef(readerId);
        }
        else
        {
            throw new InvalidOperationException($"Unsupported argument type: {arg.GetType().Name}");
        }
    }

