        }
        else if (arg is Compiler.ConstTerm constArg)
        {
            var (writerId, readerId) = runtime.Heap.AllocateVariable();
            runtime.Heap.BindWriterConst(writerId, constArg.Value);
            argSlots[argSlot] = new RtVarRef(readerId);
