        else if (arg is Compiler.StructTerm structArg)
        {
            var (writerId, readerId) = runtime.Heap.AllocateVariable();
            var structValue = _BuildStructTermForConj(runtime, structArg, queryVarWriters, varNameToId) as RtStructTerm
                              ?? throw new InvalidOperationException("BuildStructTermForConj must return RtStructTerm");
            runtime.Heap.BindWriterStruct(writerId, structValue.Functor, structValue.Args.ToList());
            argSlots[argSlot] = new RtVarRef(readerId);
        }
        else
        {
            throw new InvalidOperationException($"Unsupported argument type: {arg.GetType().Name}");
        }
    }

    private RtTerm _BuildStructTerm(
        GlpRuntimeEngine runtime,
        Compiler.StructTerm structArg,
        IDictionary<string, int> queryVarWriters,
        IDictionary<string, int> varNameToId)
    {
        var argTerms = new List<RtTerm>();

        foreach (var arg in structArg.Args)
        {
            if (arg is Compiler.ConstTerm ct)
            {
                var (writerId, readerId) = runtime.Heap.AllocateVariable();
                runtime.Heap.BindWriterConst(writerId, ct.Value);
                argTerms.Add(new RtVarRef(readerId));
            }
            else if (arg is VarTerm vt)
            {
                var baseName = vt.Name;
                if (varNameToId.TryGetValue(baseName, out var existingId))
                {
                    argTerms.Add(new RtVarRef(vt.IsReader
                        ? runtime.Heap.PairedReaderAddr(existingId)
                        : existingId));
                }
                else
                {
                    var (writerId, readerId) = runtime.Heap.AllocateVariable();
                    varNameToId[baseName] = writerId;
                    if (!vt.IsReader)
                        queryVarWriters[baseName] = writerId;
                    argTerms.Add(new RtVarRef(vt.IsReader ? readerId : writerId));
                }
            }
            else if (arg is ListTerm lt)
            {
                if (lt.IsNil)
                {
                    var (writerId, readerId) = runtime.Heap.AllocateVariable();
                    runtime.Heap.BindWriterConst(writerId, "nil");
                    argTerms.Add(new RtVarRef(readerId));
                }
                else
                {
                    var (writerId, readerId) = runtime.Heap.AllocateVariable();
                    var listValue = _BuildListTerm(runtime, lt, queryVarWriters, varNameToId) as RtStructTerm
                                    ?? throw new InvalidOperationException("BuildListTerm must return RtStructTerm for non-nil list");
                    runtime.Heap.BindWriterStruct(writerId, listValue.Functor, listValue.Args.ToList());
                    argTerms.Add(new RtVarRef(readerId));
                }
            }
            else if (arg is Compiler.StructTerm st)
            {
                var (writerId, readerId) = runtime.Heap.AllocateVariable();
                var structValue = _BuildStructTerm(runtime, st, queryVarWriters, varNameToId) as RtStructTerm
                                  ?? throw new InvalidOperationException("BuildStructTerm must return RtStructTerm");
                runtime.Heap.BindWriterStruct(writerId, structValue.Functor, structValue.Args.ToList());
                argTerms.Add(new RtVarRef(readerId));
            }
            else
            {
                throw new InvalidOperationException($"Unsupported struct argument type: {arg.GetType().Name}");
            }
        }

        return new RtStructTerm(structArg.Functor, argTerms);
    }

    /// <summary>Mirror of _BuildStructTerm for conjunction goals. Preserved separate per Dart-source fidelity.</summary>
    private RtTerm _BuildStructTermForConj(
        GlpRuntimeEngine runtime,
        Compiler.StructTerm structArg,
        IDictionary<string, int> queryVarWriters,
        IDictionary<string, int> varNameToId)
    {
        var argTerms = new List<RtTerm>();

        foreach (var arg in structArg.Args)
        {
            if (arg is Compiler.ConstTerm ct)
            {
                var (writerId, readerId) = runtime.Heap.AllocateVariable();
                runtime.Heap.BindWriterConst(writerId, ct.Value);
                argTerms.Add(new RtVarRef(readerId));
            }
            else if (arg is VarTerm vt)
            {
                var baseName = vt.Name;
                if (varNameToId.TryGetValue(baseName, out var existingId))
                {
                    argTerms.Add(new RtVarRef(vt.IsReader
                        ? runtime.Heap.PairedReaderAddr(existingId)
                        : existingId));
                }
                else
                {
                    var (writerId, readerId) = runtime.Heap.AllocateVariable();
                    varNameToId[baseName] = writerId;
                    if (!vt.IsReader)
                        queryVarWriters[baseName] = writerId;
                    // Conj variant: ternary-outside-RtVarRef-constructor (preserved verbatim).
                    argTerms.Add(vt.IsReader ? new RtVarRef(readerId) : new RtVarRef(writerId));
                }
            }
            else if (arg is ListTerm lt)
            {
                if (lt.IsNil)
                {
                    var (writerId, readerId) = runtime.Heap.AllocateVariable();
                    runtime.Heap.BindWriterConst(writerId, "nil");
                    argTerms.Add(new RtVarRef(readerId));
                }
                else
                {
                    var (writerId, readerId) = runtime.Heap.AllocateVariable();
                    var listValue = _BuildListTermForConj(runtime, lt, queryVarWriters, varNameToId) as RtStructTerm
                                    ?? throw new InvalidOperationException("BuildListTermForConj must return RtStructTerm for non-nil list");
                    runtime.Heap.BindWriterStruct(writerId, listValue.Functor, listValue.Args.ToList());
                    argTerms.Add(new RtVarRef(readerId));
                }
            }
            else if (arg is Compiler.StructTerm st)
            {
                var (writerId, readerId) = runtime.Heap.AllocateVariable();
                var structValue = _BuildStructTermForConj(runtime, st, queryVarWriters, varNameToId) as RtStructTerm
                                  ?? throw new InvalidOperationException("BuildStructTermForConj must return RtStructTerm");
                runtime.Heap.BindWriterStruct(writerId, structValue.Functor, structValue.Args.ToList());
                argTerms.Add(new RtVarRef(readerId));
            }
            else
            {
                throw new InvalidOperationException($"Unsupported struct argument type: {arg.GetType().Name}");
            }
        }

        return new RtStructTerm(structArg.Functor, argTerms);
    }

    private RtTerm _BuildListTerm(
        GlpRuntimeEngine runtime,
        ListTerm list,
        IDictionary<string, int> queryVarWriters,
        IDictionary<string, int> varNameToId)
    {
        if (list.IsNil)
            return new RtConstTerm("nil");

        var head = list.Head!;
        var tail = list.Tail;

        RtTerm headTerm;
        if (head is Compiler.ConstTerm ct)
        {
            headTerm = new RtConstTerm(ct.Value);
        }
        else if (head is VarTerm vt)
        {
            var baseName = vt.Name;
            if (varNameToId.TryGetValue(baseName, out var existingId))
            {
                headTerm = new RtVarRef(vt.IsReader
                    ? runtime.Heap.PairedReaderAddr(existingId)
                    : existingId);
            }
            else
            {
                var (writerId, readerId) = runtime.Heap.AllocateVariable();
                varNameToId[baseName] = writerId;
                if (!vt.IsReader)
                    queryVarWriters[baseName] = writerId;
                headTerm = new RtVarRef(vt.IsReader ? readerId : writerId);
            }
        }
        else if (head is ListTerm lt)
        {
            headTerm = _BuildListTerm(runtime, lt, queryVarWriters, varNameToId);
        }
        else if (head is Compiler.StructTerm st)
        {
            headTerm = _BuildStructTerm(runtime, st, queryVarWriters, varNameToId);
        }
        else
        {
            throw new InvalidOperationException($"Unsupported list head type: {head.GetType().Name}");
        }

        RtTerm tailTerm;
        if (tail is ListTerm tailList)
        {
            tailTerm = _BuildListTerm(runtime, tailList, queryVarWriters, varNameToId);
        }
        else if (tail is VarTerm tailVt)
        {
            var baseName = tailVt.Name;
            if (varNameToId.TryGetValue(baseName, out var existingId))
            {
                tailTerm = new RtVarRef(tailVt.IsReader
                    ? runtime.Heap.PairedReaderAddr(existingId)
                    : existingId);
            }
            else
            {
                var (writerId, readerId) = runtime.Heap.AllocateVariable();
                varNameToId[baseName] = writerId;
                if (!tailVt.IsReader)
                    queryVarWriters[baseName] = writerId;
                tailTerm = new RtVarRef(tailVt.IsReader ? readerId : writerId);
            }
        }
        else
        {
            tailTerm = new RtConstTerm(null);
        }

        // List-cell functor "." preserved verbatim.
        return new RtStructTerm(".", new List<RtTerm> { headTerm, tailTerm });
    }

